<script lang="ts">
  import { onMount } from 'svelte';
  import BrokerExecution from './BrokerExecution.svelte';
  type Run={id:string;datasetName:string;status:string;config:{hypothesis:string;monthlyGbp:number}};
  type Order={id:string;period:string;intent:{symbol:string;quantity:number;limitPrice:number;maximumDebitGbp:number};progress:{status:string;filled:number;debitGbp:number;remainingReserve:number}};
  type Account={id:string;runId:string;cashGbp:number;contributionsGbp:number;quantities:Record<string,number>;orders:Order[];decisions:{month:string;signalDate:string;weights:Record<string,number>;notes:string[]}[]};
  type Capabilities={broker:{mode:string;credentialsConfigured:boolean;automaticPurchases:boolean;gates:string[]}};
  let runs=$state<Run[]>([]),accounts=$state<Account[]>([]),capabilities=$state<Capabilities|null>(null),runId=$state(''),month=$state(new Date().toISOString().slice(0,7)),paused=$state(false),busy=$state(false),error=$state(''),selected=$state(''),summary=$state('');
  let requestId='';
  const account=$derived(accounts.find(a=>a.id===selected)??accounts[0]);
  const reserved=$derived(account?.orders.reduce((total,o)=>total+o.progress.remainingReserve,0)??0);
  const money=(x:number)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(x);
  async function api(path:string,body?:unknown){const r=await fetch(path,body===undefined?undefined:{method:'POST',headers:{'X-Twenty-Request':'1','Content-Type':'application/json'},body:JSON.stringify(body)});const value=await r.json();if(!r.ok)throw new Error(value.error??'service-unavailable');return value;}
  async function refresh(){const result=await api('/api/execution/paper');accounts=result.accounts;paused=result.paused;if(!accounts.some(a=>a.id===selected))selected=accounts[0]?.id??'';}
  async function action(path:string,body:unknown={}){busy=true;error='';try{const result=await api(path,body);if(result.id)selected=result.id;await refresh();}catch(e){error=e instanceof Error?e.message:'operation-failed';}finally{busy=false;}}
  async function rehearse(){busy=true;error='';requestId ||= crypto.randomUUID();try{const result=await api('/api/execution/paper',{requestId,runId,month});requestId='';selected=result.id;await refresh();}catch(e){error=e instanceof Error?e.message:'rehearsal-failed';}finally{busy=false;}}
  async function readBroker(){busy=true;error='';try{const result=await api('/api/execution/broker/summary');const inAccountCurrency=(x:number)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:result.currency}).format(x);summary=`${result.environment} · account ${result.account} · available ${inAccountCurrency(result.cash.availableToTrade)}. ISA identity is not supplied by this endpoint.`;}catch(e){error=e instanceof Error?e.message:'broker-unavailable';}finally{busy=false;}}
  onMount(()=>{void Promise.all([api('/api/research/runs'),api('/api/research/capabilities'),refresh()]).then(([all,cap])=>{runs=all.filter((r:Run)=>r.status==='succeeded');runId=runs[0]?.id??'';capabilities=cap;}).catch(e=>error=e.message);});
</script>
<div class="page-heading"><div><p class="eyebrow">DECISIONS & ORDERS</p><h1>From a model choice<br/><em>to an accounted purchase.</em></h1><p class="intro">Inspect model choices and rehearse purchases with simulated money.<br/>Current signals and the separate broker journal are below.</p></div><div class="mode-stamp"><span>HISTORICAL REHEARSAL</span><strong>Simulated money<br/>in this section</strong><small>{paused?'New decisions paused':'Ready to rehearse'}</small></div></div>
<div class="bottom-grid">
<section class="panel compact execution-config"><p class="eyebrow">FROZEN MODEL → BUY PLAN</p><h2>Let the application choose.</h2><p>Use the last historical model targets from a completed experiment. Each run starts a separate simulated portfolio; this does not replay the backtest's accumulated holdings. Rehearsing repeats that frozen allocation; it does not produce a new market forecast.</p>
<form onsubmit={(e)=>{e.preventDefault();void rehearse();}}><label>Completed experiment<select bind:value={runId} required>{#each runs as r}<option value={r.id}>{r.config.hypothesis} · {r.datasetName} · {r.id.slice(0,8)}</option>{/each}</select></label><label>Simulated contribution month<input type="month" bind:value={month} required min="2000-01" max="2200-12"/></label><p class="dataset-note">One configured contribution per month, in sequence. Pending fills must be reconciled first. The buy planner rounds share quantities down, reserves fees and leaves below-minimum amounts as cash.</p><button disabled={busy||paused||!runId} type="submit">Create simulated buy orders ↗</button></form>
{#if !runs.length}<p class="dataset-note">Complete an experiment in the <a href="#research">growth lab</a> first.</p>{/if}
<button class="secondary" disabled={busy} onclick={()=>void action(`/api/execution/pause?paused=${!paused}`)}>{paused?'Resume new submissions':'Pause all new submissions'}</button><p class="dataset-note">Pausing survives restarts and also stops new broker submissions. Reconciliation and cancellation remain available.</p></section>
<section class="panel compact broker-card"><p class="eyebrow">TRADING 212 ADAPTER</p><h2>{capabilities?.broker.credentialsConfigured?'Credentials configured':'Ready for private setup.'}</h2><p>The quantity-limit transport is implemented and tested against simulated HTTP responses. Broker credentials belong in private mounted files. The durable coordinator, current-signal scoring and private execution settings are available below. This rehearsal stays isolated from broker execution.</p><div class="lab-metrics"><div><span>Broker environment</span><strong>{capabilities?.broker.mode??'Loading…'}</strong></div><div><span>Automatic real purchases</span><strong>{capabilities?.broker.automaticPurchases?'Configured':'Not configured'}</strong></div></div><button class="secondary" disabled={busy||!capabilities?.broker.credentialsConfigured} onclick={()=>void readBroker()}>Read account summary</button>{#if summary}<p class="dataset-note">{summary}</p>{/if}<p>Remaining inputs for real execution:</p><ul class="limitations">{#each capabilities?.broker.gates??[] as gate}<li>{gate}</li>{/each}</ul><a class="text-link" href="https://github.com/Jellman86/twenty/blob/dev/docs/trading212-setup.md" target="_blank" rel="noreferrer">API key and account setup instructions ↗</a></section>
</div>
{#if error}<p class="error" role="alert">{error}</p>{/if}
<section class="panel lab-results"><div class="panel-heading"><div><p class="eyebrow">PERSISTENT PAPER LEDGER</p><h2>Every pound has a place.</h2></div>{#if accounts.length}<label>Simulated portfolio<select bind:value={selected}>{#each accounts as a}<option value={a.id}>{a.runId.slice(0,8)} · {a.decisions.length} months</option>{/each}</select></label>{/if}</div>
{#if account}<div class="lab-metrics"><div><span>Contributions</span><strong>{money(account.contributionsGbp)}</strong></div><div><span>Cash balance</span><strong>{money(account.cashGbp)}</strong></div><div><span>Reserved for unfilled orders</span><strong>{money(reserved)}</strong></div><div><span>Unreserved cash</span><strong>{money(account.cashGbp-reserved)}</strong></div></div>
<div class="execution-actions"><button class="secondary" disabled={busy||!reserved} onclick={()=>void action(`/api/execution/paper/${account.id}/reconcile?partial=true`)}>Simulate partial fills</button><button disabled={busy||!reserved} onclick={()=>void action(`/api/execution/paper/${account.id}/reconcile`)}>Simulate remaining fills</button><button class="secondary" disabled={busy||!reserved} onclick={()=>void action(`/api/execution/paper/${account.id}/cancel`)}>Cancel unfilled remainder</button></div><p class="dataset-note">Fill price equals the synthetic limit; fee equals the explicit reserve. Repeated reconciliation cannot double-charge cash or duplicate holdings. No return or profit is modelled here.</p>
<div class="table-scroll"><table><thead><tr><th>Month / asset</th><th>Status</th><th>Ordered shares</th><th>Filled shares</th><th>Limit GBP</th><th>Debited GBP</th><th>Reserve GBP</th></tr></thead><tbody>{#each account.orders as order}<tr><td>{order.period} · {order.intent.symbol}</td><td>{order.progress.status}</td><td>{order.intent.quantity.toFixed(4)}</td><td>{order.progress.filled.toFixed(4)}</td><td>{money(order.intent.limitPrice)}</td><td>{money(order.progress.debitGbp)}</td><td>{money(order.progress.remainingReserve)}</td></tr>{/each}</tbody></table></div>
<details><summary>Frozen decisions and holdings</summary><p>{Object.entries(account.quantities).map(([symbol,quantity])=>`${symbol}: ${quantity.toFixed(4)} shares`).join(' · ')||'No filled holdings yet.'}</p>{#each account.decisions as decision}<p><strong>{decision.month}</strong> · historical signal {decision.signalDate} · {Object.entries(decision.weights).map(([symbol,weight])=>`${symbol} ${(weight*100).toFixed(1)}%`).join(' · ')||'All cash'}</p><ul class="limitations">{#each decision.notes as note}<li>{note}</li>{/each}</ul>{/each}</details>
{:else}<div class="lab-empty"><h3>The next step is a recorded decision.</h3><p>Choose a completed experiment and create its simulated monthly orders.</p></div>{/if}
</section>

<BrokerExecution />
